#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiSPI.h>
#include <wiringPi.h>

#define MIN_SPEED 50
#define MAX_SPEED 255
#define POT_1_CHANNEL 0
#define POT_2_CHANNEL 1
#define MOTOR_1_ENABLE 18
#define MOTOR_1_DIRECTION 23
#define MOTOR_2_ENABLE 24
#define MOTOR_2_DIRECTION 25

void sigint_handler(int signo) {
    printf("Caught SIGINT, exiting...\n");
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signo) {
    printf("Caught SIGTERM, exiting...\n");
    gpioTerminate();
    exit(0);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO\n");
        exit(1);
    }
    gpioSetSignalFunc(SIGINT, sigint_handler);
    gpioSetSignalFunc(SIGTERM, sigterm_handler);
}

void init_spi() {
    if (wiringPiSPISetup(0, 1000000) < 0) {
        printf("Error initializing SPI\n");
        exit(1);
    }
}

void init_motors() {
    gpioSetMode(MOTOR_1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR_2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_2_DIRECTION, PI_OUTPUT);
}

void set_motor_speed(int motor, int speed) {
    if (speed < 0) {
        gpioWrite(motor, 0);
        gpioPWM(motor, 0);
    } else {
        gpioWrite(motor, 1);
        gpioPWM(motor, speed);
    }
}

void set_motor_direction(int motor, int direction) {
    if (direction == 0) {
        gpioWrite(motor, 0);
    } else {
        gpioWrite(motor, 1);
    }
}

void set_motor_speed_direction(int motor, int speed, int direction) {
    set_motor_speed(motor, speed);
    set_motor_direction(motor, direction);
}

void set_motors_speed_direction(int speed_1, int direction_1, int speed_2, int direction_2) {
    set_motor_speed_direction(MOTOR_1_ENABLE, speed_1, direction_1);
    set_motor_speed_direction(MOTOR_2_ENABLE, speed_2, direction_2);
}

void set_motors_speed(int speed_1, int speed_2) {
