#define RELAY_PINS 4
#define RELAY_PINS_ARRAY {17, 22, 23, 24}

static int relay_pins[RELAY_PINS] = RELAY_PINS_ARRAY;
static int relay_pins_active[RELAY_PINS] = {0, 0, 0, 0};

static void signal_handler(int signum) {
    int i;
    for (i = 0; i < RELAY_PINS; i++) {
        gpiod_line_set_value(relay_pins[i], 0);
    }
    gpiod_close(relay_pins[0]);
    gpiod_close(relay_pins[1]);
    gpiod_close(relay_pins[2]);
    gpiod_close(relay_pins[3]);
    exit(0);
}

int main(void) {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request line_request;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open failed\n");
        exit(1);
    }

    for (i = 0; i < RELAY_PINS; i++) {
        line_request.consumer = "relay_sequencer";
        line_request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        line_request.line = relay_pins[i];
        line = gpiod_chip_get_line(chip, &line_request);
        if (line == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed\n");
            exit(1);
        }
        relay_pins_active[i] = line;
    }

    while (1) {
        for (i = 0; i < RELAY_PINS; i++) {
            gpiod_line_set_value(relay_pins_active[i], 1);
            sleep(1);
            gpiod_line_set_value(relay_pins_active[i], 0);
            sleep(1);
        }
    }

    return 0;
}

