                    /* fall through */
                default:
                    errno_exit("VIDIOC_DQBUF");
                }
            }

            for (i = 0; i < n_buffers; ++i) {
                if (buf.index == i) {
                    process_image(buffers[i].start, buf.bytesused);
                    break;
                }
            }

            if (-1 == xioctl(fd, VIDIOC_QBUF, &buf))
                errno_exit("VIDIOC_QBUF");
        }
    }

    stop_capturing();
    uninit_device();
    close_device();

    return ret;
}

