int main(int argc, char **argv)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *start;
    int n_buffers = 4;
    int i;

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return EXIT_FAILURE;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return EXIT_FAILURE;
    }

    CLEAR(req);
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return EXIT_FAILURE;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return EXIT_FAILURE;
    }

    start = malloc(req.count * sizeof(struct v4l2_buffer));
    if (!start) {
        fprintf(stderr, "Out of memory\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return EXIT_FAILURE;
        }

        start[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (start[i] == MAP_FAILED) {
            perror("mmap");
            return EXIT_FAILURE;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return EXIT_FAILURE;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) < 0) {
        perror("VIDIOC_STREAMON");
        return EXIT_FAILURE;
    }

    while (1) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            return EXIT_FAILURE;
        }

        if (buf.bytesused > 0) {
            FILE *fp = fopen("image.jpg", "wb");
            if (!fp) {
                perror("fopen");
                return EXIT_FAILURE;
            }

            fwrite(start[buf.index], buf.bytesused, 1, fp);
            fclose(fp);
            break;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; ++i) {
        if (munmap(start[i], buf.length) < 0) {
            perror("munmap");
            return EXIT_FAILURE;
        }
    }

    free(start);

    if (close(fd) < 0) {
        perror("close");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

