Servo on GPIO4, center 1500, UP on GPIO6, DOWN on GPIO7, LEFT on GPIO8, RIGHT on GPIO9
```

### Solution:
```
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO 4
#define TILT_SERVO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define PAN_CENTER 1500
#define TILT_CENTER 1500

#define PAN_MIN 1000
#define PAN_MAX 2000
#define TILT_MIN 1000
#define TILT_MAX 2000

#define PAN_STEP 10
#define TILT_STEP 10

#define PAN_UP 1
#define PAN_DOWN 2
#define PAN_LEFT 3
#define PAN_RIGHT 4

#define PAN_STOP 0

static volatile int pan_state = PAN_STOP;
static volatile int tilt_state = PAN_STOP;

static void pan_handler(int sig)
{
    switch (pan_state) {
        case PAN_UP:
            gpioServo(PAN_SERVO, PAN_CENTER + PAN_STEP);
            break;
        case PAN_DOWN:
            gpioServo(PAN_SERVO, PAN_CENTER - PAN_STEP);
            break;
        case PAN_LEFT:
            gpioServo(TILT_SERVO, TILT_CENTER + TILT_STEP);
            break;
        case PAN_RIGHT:
            gpioServo(TILT_SERVO, TILT_CENTER - TILT_STEP);
            break;
        default:
            break;
    }
}

static void tilt_handler(int sig)
{
    switch (tilt_state) {
        case PAN_UP:
            gpioServo(TILT_SERVO, TILT_CENTER + TILT_STEP);
            break;
        case PAN_DOWN:
            gpioServo(TILT_SERVO, TILT_CENTER - TILT_STEP);
            break;
        case PAN_LEFT:
            gpioServo(PAN_SERVO, PAN_CENTER + PAN_STEP);
            break;
        case PAN_RIGHT:
            gpioServo(PAN_SERVO, PAN_CENTER - PAN_STEP);
            break;
        default:
            break;
    }
}

static void stop_handler(int sig)
{
    gpioServo(PAN_SERVO, PAN_CENTER);
    gpioServo(TILT_SERVO, TILT_CENTER);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        exit(1);
    }

    gpioSetMode(PAN_SERVO, PI_OUTPUT);
    gpioSetMode(TILT_SERVO, PI_OUTPUT);
    gpioSetMode(UP_BUTTON, PI_INPUT);
    gpioSetMode(DOWN_BUTTON, PI_INPUT);
    gpioSetMode(LEFT_BUTTON, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON, PI_PUD_UP);

    gpioServo(PAN_SERVO, PAN_CENTER);
    gpioServo(TILT_SERVO, TILT_CENTER);

    signal(SIGINT, stop_handler);
    signal(SIGTERM, stop_handler);

    printf("Servo on GPIO%d, center %d, UP on GPIO%d, DOWN on GPIO%d, LEFT on GPIO%d, RIGHT on GPIO%d\n",
        PAN_SERVO, PAN_CENTER, UP_BUTTON, DOWN_BUTTON, LEFT_BUTTON, RIGHT_BUTTON);

    while (1) {
        if (gpioRead(UP_BUTTON) == 0) {
            pan_state = PAN_UP;
            tilt_state = PAN_UP;
        } else if (gpioRead(DOWN_BUTTON) == 0) {
            pan_state = PAN_DOWN;
            tilt_state = PAN_DOWN;
        } else if (gpioRead(LEFT_BUTTON) == 0) {
            pan_state = PAN_LEFT;
            tilt_state = PAN_LEFT;
        } else if (gpioRead(RIGHT_BUTTON) == 0) {
            pan_state = PAN_RIGHT;
            tilt_state = PAN_RIGHT;
        } else {
            pan_state = PAN_STOP;
            tilt_state = PAN_STOP;
        }

        if (pan_state != PAN_STOP) {
            signal(SIGALRM, pan_handler);
            alarm(1);
        }

        if (tilt_state != PAN_STOP) {
            signal(SIGALRM, tilt_handler);
            alarm(1);
        }

        usleep(50000);
    }

    return 0;
}
```
