### Solution:
```
#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>

#define LED 17
#define BUTTON 18
#define SERVO 19

#define SERVO_CENTER 1500
#define SERVO_MIN 1000
#define SERVO_MAX 2000

#define SERVO_STEP 10

#define SERVO_UP 1
#define SERVO_DOWN 2

#define SERVO_STOP 0

#define PAN_SERVO 4
#define TILT_SERVO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define PAN_CENTER 1500
#define TILT_CENTER 1500

#define PAN_MIN 1000
#define PAN_MAX 2000
#define TILT_MIN 1000
#define TILT_MAX 2000

#define PAN_STEP 10
#define TILT_STEP 10

#define PAN_UP 1
#define PAN_DOWN 2
#define PAN_LEFT 3
#define PAN_RIGHT 4

#define PAN_STOP 0

static volatile int pan_state = PAN_STOP;
static volatile int tilt_state = PAN_STOP;

static void pan_handler(int sig)
{
    switch (pan_state) {
        case PAN_UP:
            pwmWrite(PAN_SERVO, PAN_CENTER + PAN_STEP);
            break;
        case PAN_DOWN:
            pwmWrite(PAN_SERVO, PAN_CENTER - PAN_STEP);
            break;
        case PAN_LEFT:
            pwmWrite(TILT_SERVO, TILT_CENTER + TILT_STEP);
            break;
        case PAN_RIGHT:
            pwmWrite(TILT_SERVO, TILT_CENTER - TILT_STEP);
            break;
        default:
            break;
    }
}

static void tilt_handler(int sig)
{
    switch (tilt_state) {
        case PAN_UP:
            pwmWrite(TILT_SERVO, TILT_CENTER + TILT_STEP);
            break;
        case PAN_DOWN:
            pwmWrite(TILT_SERVO, TILT_CENTER - TILT_STEP);
            break;
        case PAN_LEFT:
            pwmWrite(PAN_SERVO, PAN_CENTER + PAN_STEP);
            break;
        case PAN_RIGHT:
            pwmWrite(PAN_SERVO, PAN_CENTER - PAN_STEP);
            break;
        default:
            break;
    }
}

static void stop_handler(int sig)
{
    pwmWrite(PAN_SERVO, PAN_CENTER);
    pwmWrite(TILT_SERVO, TILT_CENTER);
    wiringPiSetup();
    exit(0);
}

int main(void)
{
    if (wiringPiSetup() < 0) {
        fprintf(stderr, "wiringPiSetup() failed\n");
        exit(1);
    }

    pinMode(LED, PWM_OUTPUT);
    pinMode(BUTTON, INPUT);
    pinMode(SERVO, PWM_OUTPUT);
    pinMode(PAN_SERVO, PWM_OUTPUT);
    pinMode(TILT_SERVO, PWM_OUTPUT);
    pinMode(UP_BUTTON, INPUT);
    pinMode(DOWN_BUTTON, INPUT);
    pinMode(LEFT_BUTTON, INPUT);
    pinMode(RIGHT_BUTTON, INPUT);

    while (1) {
        if (digitalRead(BUTTON) == HIGH) {
            pwmWrite(LED, 255);
            servo_state = SERVO_UP;
        } else {
            pwmWrite(LED, 0);
            servo_state = SERVO_DOWN;
        }

        if (servo_state != SERVO_STOP) {
            signal(SIGALRM, servo_handler);
            alarm(1);
        }

        if (digitalRead(UP_BUTTON) == HIGH) {
            pan_state = PAN_UP;
            tilt_state = PAN_UP;
        } else if (digitalRead(DOWN_BUTTON) == HIGH) {
            pan_state = PAN_DOWN;
            tilt_state = PAN_DOWN;
        } else if (digitalRead(LEFT_BUTTON) == HIGH) {
            pan_state = PAN_LEFT;
            tilt_state = PAN_LEFT;
        } else if (digitalRead(RIGHT_BUTTON) == HIGH) {
            pan_state = PAN_RIGHT;
            tilt_state = PAN_RIGHT;
        } else {
            pan_state = PAN_STOP;
            tilt_state = PAN_STOP;
        }

        if (pan_state != PAN_STOP) {
            signal(SIGALRM, pan_handler);
            alarm(1);
        }

        if (tilt_state != PAN_STOP) {
            signal(SIGALRM, tilt_handler);
            alarm(1);
        }

        usleep(50000);
    }

    return 0;
}
