static void sigint_handler(int signum)
{
    syslog(LOG_INFO, "SIGINT received, shutting down");
    gpioPWM(red_fd, 0);
    gpioPWM(green_fd, 0);
    gpioPWM(blue_fd, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

static void sigterm_handler(int signum)
{
    syslog(LOG_INFO, "SIGTERM received, shutting down");
    gpioPWM(red_fd, 0);
    gpioPWM(green_fd, 0);
    gpioPWM(blue_fd, 0);
