```
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_SERVO 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define LOCK_PULSE 2000
#define UNLOCK_PULSE 1000
#define DEBOUNCE_DELAY 100000

static volatile int running = 1;

void handle_signal(int signum)
{
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, handle_signal) < 0) {
        fprintf(stderr, "gpioSetSignalFunc() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGTERM, handle_signal) < 0) {
        fprintf(stderr, "gpioSetSignalFunc() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioServo(LOCK_SERVO, LOCK_PULSE) < 0) {
        fprintf(stderr, "gpioServo() failed\n");
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking...\n");
            if (gpioServo(LOCK_SERVO, LOCK_PULSE) < 0) {
                fprintf(stderr, "gpioServo() failed\n");
                return EXIT_FAILURE;
            }
            usleep(DEBOUNCE_DELAY);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking...\n");
            if (gpioServo(LOCK_SERVO, UNLOCK_PULSE) < 0) {
                fprintf(stderr, "gpioServo() failed\n");
                return EXIT_FAILURE;
            }
            usleep(DEBOUNCE_DELAY);
        }

        usleep(10000);
    }

    if (gpioServo(LOCK_SERVO, 0) < 0) {
        fprintf(stderr, "gpioServo() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "gpioTerminate() failed\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
