#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define TOUCH_TIMEOUT 10000

volatile int keepRunning = 1;

void sigintHandler(int sig) {
    keepRunning = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed\n");
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    gpioWrite(RELAY_PIN, 0);

    while (keepRunning) {
        if (gpioRead(TOUCH_PIN) == 0) {
            gpioWrite(RELAY_PIN, 1);
            usleep(50000);
            gpioWrite(RELAY_PIN, 0);
