#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define BUTTON_PIN 4

volatile int keepRunning = 1;

void sigintHandler(int sig) {
    keepRunning = 0;
}

void buttonHandler(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed\n");
        return 1;
    }

    if (gpioSetAlertFunc(BUTTON_PIN, buttonHandler) < 0) {
        fprintf(stderr, "gpioSetAlertFunc() failed\n");
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    while (keepRunning) {
        usleep(100000);
    }

    gpioTerminate();

    return 0;
}
