void touchTimeoutHandler(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        gpioWrite(RELAY_PIN, 0);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode() failed\n");
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown() failed\n");
        return 1;
    }

    if (gpioSetAlertFunc(TOUCH_PIN, touchHandler) < 0) {
        fprintf(stderr, "gpioSetAlertFunc() failed\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(TOUCH_PIN, PI_TIMEOUT, TOUCH_TIMEOUT, touchTimeoutHandler) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx() failed\n");
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigintHandler);

    while (keepRunning) {
        usleep(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return 0;
}

